import {chromium} from '@playwright/test';
import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {fileURLToPath} from 'node:url';
const base='director-kit/production/evidence/P06C';
const browser=await chromium.launch({headless:true,args:['--use-angle=d3d11','--mute-audio']});
try{
 const saved=JSON.parse(await fs.readFile('director-kit/production/evidence/P04B2/fixtures/review08-earned.json','utf8'));
 const page=await browser.newPage({viewport:{width:1280,height:720},storageState:saved});
 await page.addInitScript(()=>{
  const states=new WeakMap(),textures=new WeakMap();let next=0;
  const state=gl=>{if(!states.has(gl))states.set(gl,{unit:33984,bound:new Map()});return states.get(gl)};
  const record=texture=>{if(!texture)return null;if(!textures.has(texture)){const r={id:++next,parameters:{},mipmapCalls:0};textures.set(texture,r);window.__textureUploads.push(r)}return textures.get(texture)};
  const current=(gl,target)=>record(state(gl).bound.get(state(gl).unit+':'+target));
  window.__textureUploads=[];
  const proto=WebGL2RenderingContext.prototype;
  for(const name of ['activeTexture','bindTexture','texParameteri','texParameterf','texStorage2D','texImage2D','texSubImage2D','generateMipmap']){
   const original=proto[name];proto[name]=function(...args){
    if(name==='activeTexture')state(this).unit=args[0];
    if(name==='bindTexture')state(this).bound.set(state(this).unit+':'+args[0],args[1]);
    const r=current(this,args[0]);
    if(r){
     if(name==='texParameteri'||name==='texParameterf')r.parameters[args[1]]=args[2];
     if(name==='generateMipmap')r.mipmapCalls++;
     if(name==='texStorage2D'){r.storage={levels:args[1],format:args[2],width:args[3],height:args[4]}}
     if(name==='texImage2D'||name==='texSubImage2D'){
      const image=args.at(-1);if(image?.width&&image?.height)r.image={width:image.width,height:image.height,type:image.constructor.name};
     }
    }
    return original.apply(this,args);
   }
  }
 });
 await page.goto('http://127.0.0.1:5187/?scene=crew&test=1');
 await page.waitForFunction(()=>window.__CREW?.ready,null,{timeout:120000});
 await page.waitForTimeout(500);
 const result=await page.evaluate(()=>({runtime:window.__CREW.inspect().commit,renderer:window.__CREW.inspect().renderer,materials:window.__CREW.inspect().showcase.materialBindings.filter(m=>m.name==='P06C_Palm_Frond'),candidates:window.__textureUploads.filter(r=>r.image?.width===512&&r.image?.height===1024),attributes:document.querySelector('canvas').getContext('webgl2').getContextAttributes()}));
 const manifest=JSON.parse(await fs.readFile('dist/review-build.json','utf8'));
 const report={method:'Unscored isolated native renderer upload instrumentation after timing matrix. Actual512x1024 ImageBitmap uploads identify the unique authored frond dimensions; exact embedded PNG identity is independently tested. Records WebGL texture storage/filter/mipmap calls, not just glTF declarations. No alpha-to-coverage claim or timing score.',manifestCommit:manifest.commit,toolSource:await fs.readFile(fileURLToPath(import.meta.url),'utf8'),...result};
 await fs.writeFile(base+'/runtime-sampler-report.json',JSON.stringify(report,null,2));
 assert.equal(result.runtime,manifest.buildRef);assert.ok(result.candidates.length);
 for(const r of result.candidates){assert.equal(r.parameters[10241],9987,'LINEAR_MIPMAP_LINEAR');assert.equal(r.parameters[10240],9729,'LINEAR magnification');assert.ok(r.mipmapCalls>0);assert.ok(r.storage.levels>1)}
 assert.ok(result.materials.every(m=>Math.abs(m.alphaTest-.35)<1e-6&&!m.transparent&&m.side===2));
 console.log(JSON.stringify(result,null,2));
}finally{await browser.close()}
